<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import api from'../../services/api';import type{PageResult}from'../../types/medical'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),filters=reactive({search:'',action:'',resource:'',dateRange:[] as string[]})
async function load(){loading.value=true;try{const{data}=await api.get<PageResult<any>>('audit-logs/',{params:{page:page.value,search:filters.search,action:filters.action||undefined,resource:filters.resource||undefined,date_from:filters.dateRange?.[0],date_to:filters.dateRange?.[1]}});rows.value=data.results;total.value=data.count}finally{loading.value=false}}
function reset(){Object.assign(filters,{search:'',action:'',resource:'',dateRange:[]});page.value=1;load()}onMounted(load)
</script>
<template><section><div class="page-heading"><div><h1>操作审计</h1><p>按操作人、资源、动作和日期追溯关键行为</p></div></div><el-card class="table-card"><div class="table-tools audit-tools"><el-input v-model="filters.search" clearable placeholder="操作人或描述" @keyup.enter="load"/><el-input v-model="filters.resource" clearable placeholder="资源，如 billing"/><el-input v-model="filters.action" clearable placeholder="动作，如 pay"/><el-date-picker v-model="filters.dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="created_at" label="时间" min-width="180"/><el-table-column prop="user_name" label="操作人"/><el-table-column prop="resource" label="资源"/><el-table-column prop="action" label="动作"/><el-table-column prop="object_id" label="对象 ID"/><el-table-column prop="description" label="说明" min-width="260" show-overflow-tooltip/></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" layout="prev,pager,next" :total="total" @change="load"/></div></el-card></section></template>
